#!/usr/bin/env python3
r"""
CivicFix v3.0 (Smart-City Multi-Layer GIS, AI Vision & Disaster-Resilient Edition) — One-Click Executable Updater
Target Directory: C:/xampp/htdocs/CivicFix (or current working directory)

What CivicFix v3.0 Fixes & Upgrades:
  1. Bulletproof Dual-Engine Leaflet 1.9.4 + Procedural Ludhiana GIS Map:
     - Loads official Leaflet 1.9.4 CSS/JS + CartoDB Voyager, Esri World Imagery Satellite, and CARTO Dark Radar tiles.
     - Places a procedural HTML5 Canvas Ludhiana Vector GIS grid underneath live tiles and intercepts 'tileerror'
       so a grey box is impossible even if internet drops or tile servers are blocked.
     - Automatic ResizeObserver + tab-switch invalidateSize() protection.
  2. Multi-Layer Smart-City GIS Overlays:
     - 150m Haversine Cluster Geofence Rings
     - Thermal Grievance Density Heatmap Layer
     - Ludhiana Municipal Ward Boundary Polygons (Zone A, B, C, D)
     - Live GPS Field Patrol & EV Response Fleet Tracker (with animated dispatch simulation)
  3. AI Computer-Vision Evidence Hazard Scanner:
     - In-browser Canvas pixel/contrast/reflection analyzer + EXIF Geo-Tag verification + 1-click Demo Scan.
  4. WhatsApp Conversational AI Bot (+91-1800-180-1916) + GSM SMS (1916) + Toll-Free 1800-IVR Gateways.
  5. Community "Me Too / Upvote (+1)" Corroboration, 4-Stage SLA Countdown Matrix & SVG QR-Coded Citizen Receipts.
"""

import os
import zlib
import base64
import urllib.request

TARGET_DIR = r"C:\xampp\htdocs\CivicFix"
if not os.path.isdir(TARGET_DIR):
    TARGET_DIR = os.getcwd()

BUNDLE = {
  'loogo.jpeg': '',
  'index.html': '',
  'sw.js': '',
  'css/style.css': '',
  'js/leaflet_offline.js': '',
  'js/map.js': '',
  'js/app.js': '',
  'database/schema.sql': '',
  'php/db.php': '',
  'php/python_client.php': '',
  'php/ai_preview.php': '',
  'php/submit_complaint.php': '',
  'php/list_complaints.php': '',
  'php/track_complaint.php': '',
  'php/complaint_details.php': '',
  'php/admin_login.php': '',
  'php/admin_logout.php': '',
  'php/update_status.php': '',
  'php/sms_ivr_webhook.php': '',
  'php/submit_feedback.php': '',
  'php/system_resilience.php': '',
  'python/app.py': '',
  'python/priority_engine.py': '',
  'python/duplicate_detector.py': '',
  'uploads/issues/sample_before_pothole.svg': '',
  'uploads/resolutions/sample_after_repaired.svg': '',
}

def main():
    print("=" * 80)
    print(" CivicFix v3.0 Smart-City GIS & AI Vision Edition — One-Click Installer")
    print(f" Target Directory: {TARGET_DIR}")
    print("=" * 80)

    for rel_path, b64_data in BUNDLE.items():
        dest_path = os.path.join(TARGET_DIR, rel_path.replace("/", os.sep))
        os.makedirs(os.path.dirname(dest_path), exist_ok=True)
        raw_bytes = zlib.decompress(base64.b64decode(b64_data))
        with open(dest_path, "wb") as fp:
            fp.write(raw_bytes)
        print(f" [OK] Installed: {rel_path} ({len(raw_bytes):,} bytes)")

    for sub in ["uploads/issues", "uploads/resolutions", "uploads/tiles"]:
        os.makedirs(os.path.join(TARGET_DIR, sub.replace("/", os.sep)), exist_ok=True)

    try:
        with urllib.request.urlopen("http://localhost/CivicFix/php/db.php?test=1", timeout=3) as resp:
            print(" [DB AUTO-MIGRATION]", resp.read().decode("utf-8", errors="ignore"))
    except Exception:
        print(" [INFO] Database auto-migration will run automatically on first load of http://localhost/CivicFix/")

    print("=" * 80)
    print(" SUCCESS! Open http://localhost/CivicFix/ and press Ctrl + F5 to launch CivicFix v3.0!")
    print("=" * 80)

if __name__ == "__main__":
    main()